import type {
	NextConfig,
} from 'next';

const nextConfig: NextConfig = {
	images: {
		remotePatterns: [
			{
				protocol: 'https',
				hostname: '**',
			},
			{
				protocol: 'http',
				hostname: '**',
			},
		],
	},
	experimental: {
		optimizePackageImports: [
			'lucide-react',
		],
	},
	// @ts-ignore - Turbopack root config exists in this version but might not be in the types yet
	turbopack: {
		root: '.',
	},
};

export default nextConfig;

import {
	PrismaClient,
} from '@prisma/client';
import readline from 'readline';
import bcrypt from 'bcryptjs';

const prisma = new PrismaClient();
const rl = readline.createInterface({
	input: process.stdin,
	output: process.stdout,
});

const ask = (question: string): Promise<string> => {
	return new Promise((resolve) => {
		rl.question(question, resolve);
	});
};

async function main() {
	console.log('\n--- Admin User Management ---\n');
	console.log('1. List Users');
	console.log('2. Create User');
	console.log('3. Delete User');
	console.log('4. Change Password');
	console.log('5. Exit');

	const choice = (await ask('\nSelect an option (1-5): ')).trim();

	switch (choice) {
	case '1':
		await listUsers();
		break;
	case '2':
		await createUser();
		break;
	case '3':
		await deleteUser();
		break;
	case '4':
		await changePassword();
		break;
	case '5':
		console.log('Exiting...');
		process.exit(0);
	default:
		console.log('Invalid option.');
	}

	// Loop
	main();
}

async function listUsers() {
	const users = await prisma.user.findMany();
	console.log('\nExisting Users:');
	if (users.length === 0) {
		console.log('  No users found.');
	}
	else {
		console.table(users.map(u => ({
			id: u.id,
			email: u.email,
			role: u.role,
		})));
	}
}

async function createUser() {
	console.log('\nCreate New User:');
	const email = await ask('Email: ');
	const password = await ask('Password: ');
	const role = await ask('Role (ADMIN/TEAM_LEADER, default ADMIN): ') || 'ADMIN';

	try {
		const hashedPassword = await bcrypt.hash(password, 10);
		await prisma.user.create({
			data: {
				email,
				password: hashedPassword,
				role,
			},
		});
		console.log(`User ${email} created successfully.`);
	}
	catch (e) {
		console.error('Error creating user (Email might already exist).', e);
	}
}

async function deleteUser() {
	await listUsers();
	const email = await ask('\nEnter Email of user to delete: ');

	try {
		await prisma.user.delete({
			where: {
				email,
			},
		});
		console.log(`User ${email} deleted.`);
	}
	catch (e) {
		console.error('Error deleting user.', e);
	}
}

async function changePassword() {
	const email = await ask('\nEnter Email of user: ');
	const newPassword = await ask('New Password: ');

	try {
		const hashedPassword = await bcrypt.hash(newPassword, 10);
		await prisma.user.update({
			where: {
				email,
			},
			data: {
				password: hashedPassword,
			},
		});
		console.log('Password updated.');
	}
	catch (e) {
		console.error('Error updating password.', e);
	}
}

main();

'use client';

import {
	trpc,
} from '@/lib/trpc';
import {
	useState, useMemo,
} from 'react';
import {
	BarChart3,
	Eye,
	ShoppingCart,
	TrendingUp,
	Users,
	Package,
	Layers,
	ArrowUpRight,
	ArrowDownRight,
	Calendar,
} from 'lucide-react';
import clsx from 'clsx';
import {
	BarChart,
	Bar,
	XAxis,
	YAxis,
	Tooltip,
	ResponsiveContainer,
	CartesianGrid,
	Area,
	AreaChart,
	Cell,
	LabelList,
} from 'recharts';
import {
	Skeleton,
} from '@/components/shared/skeleton';
import {
	motion,
} from 'framer-motion';
import {
	Tooltip as CustomTooltip,
} from '@/components/shared/ui/tooltip';

const CATEGORY_NAMES: Record<string, string> = {
	MOBILE: 'Mobilfunk',
	FIBER: 'Glasfaser',
	DSL: 'Festnetz',
	MAGENTA_TV_OTT: 'MagentaTV',
	DEVICE: 'Endger├ñte',
	ADDON: 'Zubuchoptionen',
	PAGE_VIEW: 'Seitenaufrufe',
};

const CATEGORY_COLORS: Record<string, string> = {
	MOBILE: '#e20074',
	FIBER: '#0090d0',
	DSL: '#7b61ff',
	MAGENTA_TV_OTT: '#ff6b00',
	DEVICE: '#00a878',
	ADDON: '#64748b',
	PAGE_VIEW: '#94a3b8',
};

const PERIOD_OPTIONS = [
	{
		label: '7 Tage',
		days: 7,
	},
	{
		label: '30 Tage',
		days: 30,
	},
	{
		label: '90 Tage',
		days: 90,
	},
];

export default function AnalyticsClient() {
	const [
		selectedPeriod,
		setSelectedPeriod,
	] = useState(30);

	const {
		data, isLoading,
	} = trpc.analytics.getDashboard.useQuery(
		{
			days: selectedPeriod,
		},
		{
			staleTime: 10 * 1000,
			refetchOnWindowFocus: true,
		},
	);

	// Aggregate daily data for chart
	const chartData = useMemo(() => {
		if (!data?.dailyTrend) {
			return [
			];
		}

		const map = new Map<
			string,
			{
				date: string;
				views: number;
				basket: number;
				pages: number;
				uniquePages: number;
			}
		>();

		data.dailyTrend.forEach((d: any) => {
			if (!map.has(d.date)) {
				map.set(d.date, {
					date: d.date,
					views: 0,
					basket: 0,
					pages: 0,
					uniquePages: 0,
				});
			}
			const entry = map.get(d.date)!;
			if (d.eventType === 'PRODUCT_VIEW') { entry.views += d.count; }
			else if (d.eventType === 'BASKET_ADD') { entry.basket += d.count; }
			else if (d.eventType === 'PAGE_VIEW') { entry.pages += d.count; }
			else if (d.eventType === 'UNIQUE_PAGE_VIEW') { entry.uniquePages += d.count; }
		});

		return Array.from(map.values()).sort(
			(a, b) => new Date(a.date).getTime() - new Date(b.date).getTime(),
		);
	}, [
		data?.dailyTrend,
	]);

	// Aggregate top products: group by productId, show views + basket
	const topProductsList = useMemo(() => {
		if (!data?.topProducts) {
			return [
			];
		}

		const map = new Map<
			string,
			{
				name: string;
				category: string;
				views: number;
				basket: number;
				conversionRate: number;
			}
		>();

		data.topProducts.forEach((p: any) => {
			if (!map.has(p.productId!)) {
				map.set(p.productId!, {
					name: p.name,
					category: p.category,
					views: 0,
					basket: 0,
					conversionRate: 0,
				});
			}
			const entry = map.get(p.productId!)!;
			if (p.eventType === 'PRODUCT_VIEW') { entry.views += p.count; }
			else if (p.eventType === 'BASKET_ADD') { entry.basket += p.count; }
		});

		// Calculate conversion rate per product
		const list = Array.from(map.values());
		list.forEach((p) => {
			p.conversionRate =
				p.views > 0 ? Math.round((p.basket / p.views) * 1000) / 10 : 0;
		});

		return list.sort((a, b) => b.views - a.views).slice(0, 10);
	}, [
		data?.topProducts,
	]);

	// Format date for chart axis
	const formatDate = (dateStr: string) => {
		const d = new Date(dateStr);
		return `${d.getDate()}.${d.getMonth() + 1}.`;
	};

	return (
		<div>
			{/* Header */}
			<div className="flex items-center justify-between mb-8">
				<div className="flex items-center gap-4">
					<div className="w-12 h-12 rounded-2xl bg-[#e20074]/10 flex items-center justify-center">
						<BarChart3 className="w-6 h-6 text-[#e20074]" />
					</div>
					<div>
						<h1 className="text-[1.6rem] font-extrabold text-[#1a1a2e] tracking-tight m-0">
							Statistiken
						</h1>
						<p className="text-[0.8rem] text-[#888] font-medium m-0">
							Produktaufrufe & Warenkorb-Aktivit├ñt
						</p>
					</div>
				</div>

				{/* Period Selector */}
				<div className="flex items-center gap-1 bg-[#f7f8fa] rounded-xl p-1 border border-[#eaedf0]">
					{PERIOD_OPTIONS.map((opt) => (
						<button
							key={opt.days}
							onClick={() => setSelectedPeriod(opt.days)}
							className={clsx(
								'px-4 py-2 rounded-lg text-[0.78rem] font-semibold transition-all duration-200 cursor-pointer',
								selectedPeriod === opt.days
									? 'bg-white text-[#1a1a2e] shadow-sm border border-[#eaedf0]'
									: 'text-[#888] hover:text-[#1a1a2e] border border-transparent',
							)}
						>
							<Calendar className="w-3.5 h-3.5 inline mr-1.5 -mt-0.5" />
							{opt.label}
						</button>
					))}
				</div>
			</div>

			{isLoading ? (
				<div className="space-y-6">
					<div className="grid grid-cols-4 gap-4">
						{[
							...Array(4),
						].map((_, i) => (
							<Skeleton key={i} className="h-28 rounded-2xl" />
						))}
					</div>
					<Skeleton className="h-80 rounded-2xl" />
					<div className="grid grid-cols-2 gap-4">
						<Skeleton className="h-96 rounded-2xl" />
						<Skeleton className="h-96 rounded-2xl" />
					</div>
				</div>
			) : (
				<div className="space-y-6">
					{/* KPI Cards */}
					<div className="grid grid-cols-4 gap-4">
						<KPICard
							label="Produktaufrufe"
							value={data?.kpis.totalProductViews ?? 0}
							icon={Eye}
							color="#0090d0"
							subtitle={`${selectedPeriod} Tage`}
						/>
						<KPICard
							label="In den Warenkorb"
							value={data?.kpis.totalBasketAdds ?? 0}
							icon={ShoppingCart}
							color="#00a878"
							subtitle={`${selectedPeriod} Tage`}
						/>
						<KPICard
							label="Add Rate"
							value={data?.kpis.conversionRate ?? 0}
							icon={TrendingUp}
							color="#e20074"
							suffix="%"
							subtitle="Aufrufe ÔåÆ Warenkorb"
						/>
						<KPICard
							label="Seitenaufrufe (Tgl. eindeutig)"
							value={data?.kpis.totalUniquePageViews ?? 0}
							icon={Layers}
							color="#7b61ff"
							subtitle={`Von gesamt ${data?.kpis.totalPageViews?.toLocaleString('de-DE') ?? 0} Aufrufen`}
						/>
					</div>

					{/* Trend Chart */}
					<motion.div
						initial={{
							opacity: 0,
							y: 10,
						}}
						animate={{
							opacity: 1,
							y: 0,
						}}
						transition={{
							delay: 0.1,
						}}
						className="bg-white rounded-2xl border border-[#eaedf0] p-6"
					>
						<h2 className="text-[0.95rem] font-bold text-[#1a1a2e] mb-1 tracking-tight">
							T├ñglicher Verlauf
						</h2>
						<p className="text-[0.72rem] text-[#aaa] font-medium mb-5">
							Produktaufrufe und Warenkorb-Zug├ñnge pro Tag
						</p>

						{chartData.length === 0 ? (
							<div className="h-64 flex items-center justify-center text-[#ccc] text-[0.85rem] font-medium">
								Noch keine Daten f├╝r diesen Zeitraum
							</div>
						) : (
							<div className="h-64">
								<ResponsiveContainer width="100%" height="100%">
									<AreaChart
										data={chartData}
										margin={{
											top: 5,
											right: 5,
											left: -20,
											bottom: 0,
										}}
									>
										<defs>
											<linearGradient
												id="gradViews"
												x1="0"
												y1="0"
												x2="0"
												y2="1"
											>
												<stop
													offset="5%"
													stopColor="#0090d0"
													stopOpacity={0.15}
												/>
												<stop
													offset="95%"
													stopColor="#0090d0"
													stopOpacity={0}
												/>
											</linearGradient>
											<linearGradient
												id="gradBasket"
												x1="0"
												y1="0"
												x2="0"
												y2="1"
											>
												<stop
													offset="5%"
													stopColor="#00a878"
													stopOpacity={0.15}
												/>
												<stop
													offset="95%"
													stopColor="#00a878"
													stopOpacity={0}
												/>
											</linearGradient>
										</defs>
										<CartesianGrid
											strokeDasharray="3 3"
											stroke="#f0f0f0"
											vertical={false}
										/>
										<XAxis
											dataKey="date"
											tickFormatter={formatDate}
											axisLine={false}
											tickLine={false}
											tick={{
												fontSize: 10,
												fill: '#bbb',
											}}
											interval="preserveStartEnd"
										/>
										<YAxis
											axisLine={false}
											tickLine={false}
											tick={{
												fontSize: 10,
												fill: '#bbb',
											}}
										/>
										<Tooltip
											content={({
												active, payload, label,
											}) =>
												active && payload?.length ? (
													<div className="bg-white rounded-xl shadow-lg border border-[#eaedf0] p-3 text-[0.75rem]">
														<div className="font-bold text-[#1a1a2e] mb-2 border-b border-[#f0f0f0] pb-1.5">
															{new Date(
																label as string | number,
															).toLocaleDateString('de-DE', {
																weekday: 'short',
																day: 'numeric',
																month: 'short',
															})}
														</div>
														{payload.map((p: any, i: number) => (
															<div
																key={i}
																className="flex items-center justify-between gap-4 mb-0.5"
															>
																<div className="flex items-center gap-1.5">
																	<div
																		className="w-2 h-2 rounded-full"
																		style={{
																			backgroundColor: p.color ?? '#ccc',
																		}}
																	/>
																	<span className="text-[#888]">
																		{p.name === 'views'
																			? 'Aufrufe'
																			: 'Warenkorb'}
																	</span>
																</div>
																<span className="font-bold text-[#1a1a2e]">
																	{p.value}
																</span>
															</div>
														))}
													</div>
												) : null
											}
										/>
										<Area
											type="monotone"
											dataKey="views"
											stroke="#0090d0"
											strokeWidth={2}
											fill="url(#gradViews)"
											name="views"
										/>
										<Area
											type="monotone"
											dataKey="basket"
											stroke="#00a878"
											strokeWidth={2}
											fill="url(#gradBasket)"
											name="basket"
										/>
									</AreaChart>
								</ResponsiveContainer>
							</div>
						)}

						{/* Legend */}
						<div className="flex items-center gap-6 mt-4 pt-3 border-t border-[#f0f0f0]">
							<div className="flex items-center gap-2">
								<div className="w-3 h-3 rounded-full bg-[#0090d0]" />
								<span className="text-[0.72rem] font-semibold text-[#888]">
									Produktaufrufe
								</span>
							</div>
							<div className="flex items-center gap-2">
								<div className="w-3 h-3 rounded-full bg-[#00a878]" />
								<span className="text-[0.72rem] font-semibold text-[#888]">
									In den Warenkorb
								</span>
							</div>
						</div>
					</motion.div>

					{/* Bottom Grid: Top Products + Team Usage */}
					<div className="grid grid-cols-1 lg:grid-cols-[1.2fr_0.8fr] gap-6">
						{/* Top Products */}
						<motion.div
							initial={{
								opacity: 0,
								y: 10,
							}}
							animate={{
								opacity: 1,
								y: 0,
							}}
							transition={{
								delay: 0.2,
							}}
							className="bg-white rounded-2xl border border-[#eaedf0] p-6"
						>
							<div className="flex items-center justify-between mb-5">
								<div>
									<h2 className="text-[0.95rem] font-bold text-[#1a1a2e] tracking-tight">
										Top Produkte
									</h2>
									<p className="text-[0.72rem] text-[#aaa] font-medium mt-0.5">
										Meistaufgerufene Tarife
									</p>
								</div>
								<Package className="w-5 h-5 text-[#ccc]" />
							</div>

							{topProductsList.length === 0 ? (
								<div className="py-12 text-center text-[0.85rem] text-[#ccc] font-medium">
									Noch keine Produktdaten
								</div>
							) : (
								<div className="space-y-2">
									{topProductsList.map((product, i) => {
										const catColor =
											CATEGORY_COLORS[product.category] ?? '#888';
										const maxViews = topProductsList[0]?.views ?? 1;
										const barWidth = Math.max(
											(product.views / maxViews) * 100,
											4,
										);

										return (
											<div
												key={i}
												className="flex items-center gap-3 py-2.5 px-3 rounded-xl hover:bg-[#f7f8fa] transition-colors group"
											>
												{/* Rank */}
												<span
													className={clsx(
														'w-6 h-6 rounded-lg flex items-center justify-center text-[0.65rem] font-bold shrink-0',
														i < 3
															? 'bg-[#e20074]/10 text-[#e20074]'
															: 'bg-[#f0f0f0] text-[#aaa]',
													)}
												>
													{i + 1}
												</span>

												{/* Name + Category */}
												<div className="flex-1 min-w-0">
													<div className="flex items-center gap-2 mb-1">
														<span className="text-[0.82rem] font-semibold text-[#1a1a2e] truncate">
															{product.name}
														</span>
														<span
															className="text-[0.6rem] font-bold px-1.5 py-0.5 rounded shrink-0"
															style={{
																backgroundColor: `${catColor}15`,
																color: catColor,
															}}
														>
															{CATEGORY_NAMES[product.category] ??
																product.category}
														</span>
													</div>

													{/* Mini bar */}
													<div className="h-2 bg-[#f0f0f0] rounded-full overflow-hidden">
														<div
															className="h-full rounded-full transition-all duration-500 shadow-[inset_0_1px_1px_rgba(255,255,255,0.1)]"
															style={{
																width: `${barWidth}%`,
																backgroundColor: catColor,
															}}
														/>
													</div>
												</div>

												{/* Stats */}
												<div className="flex items-center gap-4 shrink-0">
													<div className="text-right">
														<div className="text-[0.8rem] font-bold text-[#1a1a2e]">
															{product.views}
														</div>
														<div className="text-[0.6rem] text-[#aaa] font-medium">
															Aufrufe
														</div>
													</div>
													<div className="text-right">
														<div className="text-[0.8rem] font-bold text-[#00a878]">
															{product.basket}
														</div>
														<div className="text-[0.6rem] text-[#aaa] font-medium">
															Warenkorb
														</div>
													</div>
													<div className="text-right min-w-[50px]">
														<div
															className={clsx(
																'text-[0.75rem] font-bold flex items-center justify-end gap-0.5',
																product.conversionRate >= 50
																	? 'text-[#00a878]'
																	: product.conversionRate >= 20
																		? 'text-[#ff6b00]'
																		: 'text-[#aaa]',
															)}
														>
															{product.conversionRate >= 50 ? (
																<ArrowUpRight className="w-3 h-3" />
															) : product.conversionRate < 20 &&
															  product.conversionRate > 0 ? (
																	<ArrowDownRight className="w-3 h-3" />
																) : null}
															{product.conversionRate}%
														</div>
														<div className="text-[0.6rem] text-[#aaa] font-medium">
															Conv.
														</div>
													</div>
												</div>
											</div>
										);
									})}
								</div>
							)}
						</motion.div>

						{/* Right Column: Categories + Team Usage */}
						<div className="space-y-6">
							{/* Category Distribution */}
							{data?.topCategories && data.topCategories.length > 0 && (
								<motion.div
									initial={{
										opacity: 0,
										y: 10,
									}}
									animate={{
										opacity: 1,
										y: 0,
									}}
									transition={{
										delay: 0.25,
									}}
									className="bg-white rounded-2xl border border-[#eaedf0] p-6"
								>
									<div className="flex items-center justify-between mb-5">
										<h2 className="text-[0.95rem] font-bold text-[#1a1a2e] tracking-tight">
											Kategorien
										</h2>
										<Layers className="w-5 h-5 text-[#ccc]" />
									</div>
									<div className="space-y-4">
										{data.topCategories.map((c: any, i: number) => {
											const name =
												CATEGORY_NAMES[c.category?.toUpperCase() ?? ''] ??
												c.category ??
												'Unbekannt';
											const catColor =
												CATEGORY_COLORS[c.category?.toUpperCase() ?? ''] ??
												'#ccc';
											const maxCount = data.topCategories[0]?.count ?? 1;
											const barWidth = Math.max((c.count / maxCount) * 100, 3);

											return (
												<div key={i} className="flex items-center gap-3">
													<div className="w-6 h-6 rounded-lg bg-[#f0f0f0] flex items-center justify-center text-[0.65rem] font-bold text-[#aaa] shrink-0">
														{i + 1}
													</div>
													<div className="flex-1 min-w-0">
														<div className="flex items-center justify-between mb-1.5">
															<span className="text-[0.82rem] font-bold text-[#1a1a2e]">
																{name}
															</span>
															<span
																className="text-[0.78rem] font-extrabold"
																style={{
																	color: catColor,
																}}
															>
																{c.count.toLocaleString('de-DE')}
															</span>
														</div>
														<div className="h-2.5 bg-[#f0f0f0] rounded-full overflow-hidden">
															<div
																className="h-full rounded-full transition-all duration-1000 shadow-[inset_0_1px_1px_rgba(255,255,255,0.1)]"
																style={{
																	width: `${barWidth}%`,
																	backgroundColor: catColor,
																}}
															/>
														</div>
													</div>
												</div>
											);
										})}
									</div>
								</motion.div>
							)}

							{/* Team Usage */}
							{data?.teamUsage && data.teamUsage.length > 0 && (
								<motion.div
									initial={{
										opacity: 0,
										y: 10,
									}}
									animate={{
										opacity: 1,
										y: 0,
									}}
									transition={{
										delay: 0.3,
									}}
									className="bg-white rounded-2xl border border-[#eaedf0] p-6"
								>
									<div className="flex items-center justify-between mb-5">
										<h2 className="text-[0.95rem] font-bold text-[#1a1a2e] tracking-tight">
											Aktivste Teams
										</h2>
										<Users className="w-5 h-5 text-[#ccc]" />
									</div>
									<div className="space-y-4">
										{data.teamUsage.slice(0, 10).map((team: any, i: number) => {
											const maxCount = data.teamUsage[0]?.count ?? 1;
											const barWidth = Math.max(
												(team.count / maxCount) * 100,
												3,
											);

											return (
												<div key={i} className="flex items-center gap-3">
													<div className="w-6 h-6 rounded-lg bg-[#f0f0f0] flex items-center justify-center text-[0.65rem] font-bold text-[#aaa] shrink-0">
														{i + 1}
													</div>
													<div className="flex-1 min-w-0">
														<div className="flex items-center justify-between mb-1.5">
															<div className="flex flex-col">
																<span className="text-[0.82rem] font-bold text-[#1a1a2e] truncate">
																	{team.name}
																</span>
																{team.locationAddress ? (
																	<CustomTooltip content={team.locationAddress}>
																		<span className="text-[0.6rem] text-[#bbb] font-medium border-b border-dashed border-[#eaedf0] cursor-help w-fit">
																			{team.location}
																		</span>
																	</CustomTooltip>
																) : (
																	<span className="text-[0.6rem] text-[#bbb] font-medium">
																		{team.location}
																	</span>
																)}
															</div>
															<span className="text-[0.78rem] font-extrabold text-[#e20074] shrink-0 ml-2">
																{team.count.toLocaleString('de-DE')}
															</span>
														</div>
														<div className="h-2.5 bg-[#f0f0f0] rounded-full overflow-hidden">
															<div
																className="h-full rounded-full bg-[#e20074]/60 transition-all duration-1000 shadow-[inset_0_1px_1px_rgba(255,255,255,0.1)]"
																style={{
																	width: `${barWidth}%`,
																}}
															/>
														</div>
													</div>
												</div>
											);
										})}
									</div>
								</motion.div>
							)}
						</div>
					</div>
				</div>
			)}
		</div>
	);
}

// --- KPI Card Component ---
function KPICard({
	label,
	value,
	icon: Icon,
	color,
	suffix = '',
	subtitle,
}: {
	label: string;
	value: number;
	icon: React.ElementType;
	color: string;
	suffix?: string;
	subtitle?: string;
}) {
	return (
		<motion.div
			initial={{
				opacity: 0,
				y: 10,
			}}
			animate={{
				opacity: 1,
				y: 0,
			}}
			className="bg-white rounded-2xl border border-[#eaedf0] p-5 flex items-start gap-4"
		>
			<div
				className="w-11 h-11 rounded-xl flex items-center justify-center shrink-0"
				style={{
					backgroundColor: `${color}12`,
				}}
			>
				<Icon className="w-5 h-5" style={{
					color,
				}} />
			</div>
			<div>
				<span className="text-[0.72rem] font-semibold text-[#aaa] uppercase tracking-wider block mb-1">
					{label}
				</span>
				<span
					className="text-[1.6rem] font-extrabold tracking-tight leading-none"
					style={{
						color,
					}}
				>
					{typeof value === 'number' && suffix !== '%'
						? value.toLocaleString('de-DE')
						: value}
					{suffix && (
						<span className="text-[0.85rem] ml-0.5 font-bold">{suffix}</span>
					)}
				</span>
				{subtitle && (
					<span className="text-[0.65rem] text-[#ccc] font-medium block mt-1">
						{subtitle}
					</span>
				)}
			</div>
		</motion.div>
	);
}

'use client';

import {
	useState, useEffect,
} from 'react';
import Link from 'next/link';
import {
	usePathname, useRouter,
} from 'next/navigation';
import {
	Box,
	Tag,
	Settings,
	LogOut,
	Wallet,
	Users,
	ArrowLeft,
	Megaphone,
	Layers,
	Shield,
	MapPin,
	Globe,
	Activity,
	BarChart3,
} from 'lucide-react';
import clsx from 'clsx';
import {
	DeleteConfirmToast,
} from '@/components/shared/delete-confirm-toast';
import {
	trpc,
} from '@/lib/trpc';
import type {
	LucideIcon,
} from 'lucide-react';
import {
	SidebarLayout,
} from '@/components/layout/sidebar/sidebar-layout';
import {
	SidebarItem,
	SidebarGroup,
} from '@/components/layout/sidebar/sidebar-item';

interface MenuItem {
	href: string;
	label: string;
	icon: LucideIcon;
}

interface MenuGroup {
	title: string;
	show: boolean;
	items: MenuItem[];
}

export default function AdminLayout({
	children,
}: {
	children: React.ReactNode;
}) {
	const pathname = usePathname();
	const router = useRouter();

	const logoutMutation = trpc.auth.logout.useMutation({
		onSuccess: () => {
			router.push('/login');
			router.refresh();
		},
	});

	const {
		data: currentUser,
	} = trpc.auth.me.useQuery();

	const handleLogout = async () => {
		logoutMutation.mutate();
	};

	const [
		collapsed,
		setCollapsed,
	] = useState(false);

	// Keyboard shortcut: Ctrl+H to toggle sidebar
	const handleKeyDown = (e: KeyboardEvent) => {
		if (e.key === 'h' && e.ctrlKey && !e.shiftKey && !e.altKey) {
			e.preventDefault();
			setCollapsed((c) => !c);
		}
	};

	useEffect(() => {
		if (typeof document !== 'undefined') {
			document.addEventListener('keydown', handleKeyDown);
		}
		return () => {
			if (typeof document !== 'undefined') {
				document.removeEventListener('keydown', handleKeyDown);
			}
		};
	}, [
	]);

	const role = currentUser?.role;
	const isEditor = currentUser?.isEditor || role === 'ADMIN';

	const menuGroups: MenuGroup[] = [
		{
			title: 'Katalog & Konditionen',
			show: isEditor,
			items: [
				{
					href: '/admin/products',
					label: 'Produkte',
					icon: Box,
				},
				{
					href: '/admin/special-prices',
					label: 'Aktionen',
					icon: Tag,
				},
				{
					href: '/admin/addons',
					label: 'Optionen',
					icon: Layers,
				},
				{
					href: '/admin/credits',
					label: 'Gutschriften',
					icon: Wallet,
				},
			],
		},
		{
			title: 'Organisation',
			show: true,
			items: [
				...(role === 'ADMIN'
					? [
						{
							href: '/admin/od-regions',
							label: 'OD-Bereiche',
							icon: Globe,
						},
					]
					: [
					]),
				...(role === 'ADMIN' || role === 'OD_MANAGER'
					? [
						{
							href: '/admin/locations',
							label: 'Standorte',
							icon: MapPin,
						},
					]
					: [
					]),
				{
					href: '/admin/teams',
					label: 'Teams',
					icon: Users,
				},
				{
					href: '/admin/sessions',
					label: 'Sessions',
					icon: Activity,
				},
				{
					href: '/admin/analytics',
					label: 'Statistiken',
					icon: BarChart3,
				},
			],
		},
		{
			title: 'Inhalte',
			show: true,
			items: [
				{
					href: '/admin/news',
					label: 'Neuigkeiten',
					icon: Megaphone,
				},
			],
		},
		{
			title: 'System',
			show: true,
			items: [
				...(role === 'ADMIN' ||
				role === 'OD_MANAGER' ||
				role === 'LOCATION_MANAGER'
					? [
						{
							href: '/admin/users',
							label: 'Benutzer',
							icon: Shield,
						},
					]
					: [
					]),
				{
					href: '/admin/settings',
					label: 'Einstellungen',
					icon: Settings,
				},
			],
		},
	];

	return (
		<div className="min-h-screen bg-[#f7f8fa] flex text-[#333]">
			<SidebarLayout
				collapsed={collapsed}
				onToggle={() => setCollapsed(!collapsed)}
				catColor="#e20074"
				copyright={`┬® ${new Date().getFullYear()} Felix Kinze`}
				footerActions={
					<div className="px-3 w-full mb-6">
						<div
							className={clsx(
								'flex flex-col gap-0.5',
								!collapsed && 'bg-[#f7f8fa] rounded-[20px] p-2',
								collapsed && 'items-center gap-1.5',
							)}
						>
							<SidebarItem
								icon={LogOut}
								label="Abmelden"
								onClick={handleLogout}
								collapsed={collapsed}
								variant="danger"
							/>
						</div>
					</div>
				}
			>
				<nav className="flex flex-col mt-2">
					<SidebarGroup title="Navigation" collapsed={collapsed}>
						<SidebarItem
							icon={ArrowLeft}
							label="Zur├╝ck zum Sales Tool"
							href="/"
							collapsed={collapsed}
						/>
					</SidebarGroup>

					{menuGroups
						.filter((group) => group.show && group.items.length > 0)
						.map((group) => (
							<SidebarGroup
								key={group.title}
								title={group.title}
								collapsed={collapsed}
							>
								{group.items.map((item) => (
									<SidebarItem
										key={item.href}
										icon={item.icon}
										label={item.label}
										href={item.href}
										active={pathname.startsWith(item.href)}
										collapsed={collapsed}
									/>
								))}
							</SidebarGroup>
						))}
				</nav>
			</SidebarLayout>

			{/* Main content */}
			<main
				className={clsx(
					'flex-1 p-8 overflow-y-auto h-screen transition-all duration-300',
					collapsed ? 'ml-0' : 'ml-0', // We are using flex, but the aside is shrink-0. If it was fixed, we'd need margin.
				)}
			>
				<div className="max-w-[1000px] mx-auto">{children}</div>
			</main>

			<DeleteConfirmToast />
		</div>
	);
}

'use client';

import {
	useState,
} from 'react';
import {
	trpc,
} from '@/lib/trpc';
import {
	Plus, Trash2, Megaphone, Loader2, Search, Layers,
} from 'lucide-react';
import clsx from 'clsx';
import {
	format,
} from 'date-fns';
import {
	de,
} from 'date-fns/locale';
import {
	Skeleton,
} from '@/components/shared/skeleton';
import Link from 'next/link';
import {
	confirmDelete,
} from '@/components/shared/delete-confirm-toast';
import {
	AdminPageHeader,
} from '@/components/shared/ui/admin-ui';

const PRIORITY_COLORS: Record<string, string> = {
	INFO: '#00a878', // Green
	UPDATE: '#0090d0', // Blue
	IMPORTANT: '#ff6b00', // Orange
	CRITICAL: '#dc2626', // Red
};

const PRIORITY_LABELS: Record<string, string> = {
	INFO: 'Info',
	UPDATE: 'Update',
	IMPORTANT: 'Wichtig',
	CRITICAL: 'Kritisch',
};

export default function AdminNewsPage() {
	const utils = trpc.useUtils();
	const [
		searchQuery,
		setSearchQuery,
	] = useState('');

	const {
		data, isLoading, fetchNextPage, hasNextPage, isFetchingNextPage,
	} =
		trpc.admin.news.list.useInfiniteQuery(
			{
				limit: 20,
				search: searchQuery || undefined,
			},
			{
				getNextPageParam: (lastPage) => lastPage.nextCursor,
			},
		);

	const deleteNews = trpc.admin.news.delete.useMutation({
		onSuccess: () => {
			utils.admin.news.list.invalidate();
		},
	});

	const newsItems = data?.pages.flatMap((page) => page.items) || [
	];

	return (
		<div className="space-y-6 pb-20">
			<div className="flex justify-between items-center">
				<AdminPageHeader
					title="Neuigkeiten"
					subtitle="Verwalte Mitteilungen f├╝r das Dashboard."
					backHref="/admin"
				/>
				<Link
					href="/admin/news/new"
					className="flex items-center gap-2 bg-[#e20074] hover:bg-[#c70066] text-white px-5 py-2.5 rounded-xl font-semibold transition-all shadow-[0_4px_14px_rgba(226,0,116,0.25)] hover:shadow-[0_6px_20px_rgba(226,0,116,0.3)] hover:-translate-y-0.5 active:scale-95 text-[0.82rem] no-underline"
				>
					<Plus className="w-4 h-4" />
					Neuigkeit erstellen
				</Link>
			</div>

			<div className="relative">
				<Search className="w-4 h-4 text-[#bbb] absolute left-4 top-1/2 -translate-y-1/2" />
				<input
					type="text"
					placeholder="Neuigkeiten suchen..."
					value={searchQuery}
					onChange={(e) => setSearchQuery(e.target.value)}
					className="w-full pl-11 pr-4 py-3 rounded-xl border border-[#eaedf0] bg-white focus:outline-none focus:border-[#e20074]/30 focus:shadow-[0_0_0_3px_rgba(226,0,116,0.06)] transition-all text-[0.85rem]"
				/>
			</div>

			<div className="bg-white rounded-3xl border border-[#eaedf0] overflow-hidden shadow-sm">
				{isLoading && newsItems.length === 0 ? (
					<div className="flex flex-col gap-3 p-5">
						{[
							1,
							2,
							3,
							4,
							5,
						].map((i) => (
							<Skeleton key={i} className="h-20 w-full rounded-xl" />
						))}
					</div>
				) : newsItems.length === 0 ? (
					<div className="p-20 flex flex-col items-center justify-center text-center">
						<div className="w-16 h-16 bg-[#f7f8fa] rounded-2xl flex items-center justify-center mb-4 border border-[#eaedf0]">
							<Megaphone className="w-6 h-6 text-[#ccc]" />
						</div>
						<h3 className="text-[1.1rem] font-bold text-[#1a1a2e] mb-1">
							Keine Neuigkeiten
						</h3>
						<p className="text-[0.85rem] text-[#999] max-w-[250px] m-0">
							Es wurden keine Neuigkeiten f├╝r deine Suche gefunden.
						</p>
					</div>
				) : (
					<div className="flex flex-col">
						{newsItems.map(
							(
								item: {
									id: string;
									title: string;
									content: string;
									priority: string;
									createdAt: Date | string;
								},
								i: number,
							) => {
								const color =
									PRIORITY_COLORS[item.priority] || PRIORITY_COLORS.INFO;
								return (
									<div
										key={item.id}
										className={clsx(
											'px-6 py-5 flex items-start justify-between group hover:bg-[#fcfcfd] transition-colors gap-4',
											i < newsItems.length - 1 && 'border-b border-[#f0f0f0]',
										)}
									>
										<div className="flex-1">
											<div className="flex items-center gap-2 mb-1.5">
												<span
													className="px-2.5 py-1 rounded-lg text-[0.65rem] font-bold uppercase tracking-wider"
													style={{
														color,
														backgroundColor: `${color}15`,
														border: `1px solid ${color}30`,
													}}
												>
													{PRIORITY_LABELS[item.priority]}
												</span>
												<span className="text-[0.7rem] text-[#888] font-bold">
													{format(
														new Date(item.createdAt),
														'dd. MMM yyyy - HH:mm',
														{
															locale: de,
														},
													)}
												</span>
											</div>
											<h3 className="text-[1rem] font-bold text-[#1a1a2e] m-0 mb-1.5 leading-tight">
												{item.title}
											</h3>
											<p className="text-[0.85rem] text-[#666] m-0 leading-relaxed max-w-[800px]">
												{item.content}
											</p>
										</div>
										<div className="flex items-center gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
											<button
												onClick={(e) => {
													e.preventDefault();
													e.stopPropagation();
													confirmDelete({
														id: item.id,
														name: item.title,
														onConfirm: () => deleteNews.mutate({
															id: item.id,
														}),
													});
												}}
												disabled={deleteNews.isPending}
												className="p-2 text-[#ccc] hover:text-[#dc2626] hover:bg-[#fee2e2] rounded-lg transition-all cursor-pointer bg-transparent border-none disabled:opacity-50"
												title="L├Âschen"
											>
												<Trash2 className="w-4 h-4" />
											</button>
										</div>
									</div>
								);
							},
						)}
					</div>
				)}

				{hasNextPage && (
					<div className="p-8 border-t border-[#f0f0f0] flex justify-center bg-[#fcfcfd]">
						<button
							onClick={() => fetchNextPage()}
							disabled={isFetchingNextPage}
							className="flex items-center gap-2 bg-white hover:bg-[#f7f8fa] text-[#1a1a2e] px-8 py-3 rounded-2xl font-bold transition-all border border-[#eaedf0] shadow-sm hover:shadow-md active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed text-[0.85rem]"
						>
							{isFetchingNextPage ? (
								<Loader2 className="w-5 h-5 animate-spin" />
							) : (
								<Plus className="w-5 h-5" />
							)}
							{isFetchingNextPage ? 'Wird geladen...' : 'Mehr laden'}
						</button>
					</div>
				)}
			</div>
		</div>
	);
}

