														<span className="text-[0.75rem] font-medium text-[#888]">
															{session.isVerified
																? 'Verifiziert'
																: 'Ausstehend'}
														</span>
													</div>
												</div>
											</td>
											<td className="px-6 py-5">
												<div className="flex flex-col gap-1.5">
													<div className="flex items-center gap-2">
