													{session.email && (
														<div className="flex items-center gap-2 text-[0.8rem] text-[#1a1a2e] font-medium bg-[#f7f8fa] px-3 py-1.5 rounded-lg border border-[#eaedf0] w-fit">
															<Mail className="w-3.5 h-3.5 text-[#888]" />
															{session.email}
