	return (
		<motion.div
			initial={{
				opacity: 0,
				y: 10,
			}}
			animate={{
				opacity: 1,
				y: 0,
			}}
			exit={{
				opacity: 0,
				y: -10,
			}}
			className="space-y-6"
		>
			<AdminFormSection
				title="Wartungsarbeiten"
				description="Steuere die Verf├╝gbarkeit des Sales-Tools."
