																			{feature}
																		</li>
																	),
																)}
															</ul>
														</motion.div>
													)}
												</motion.div>
											);
										})}
									</motion.div>
								)}
							</div>
						</ConfigSection>
					)}

					{/* Special Prices */}
					<ConfigSection
						id="tour-config-special-prices"
						title="Aktionen & Rabatte"
						catColor={catColor}
						index={2}
					>
						<div
							className={clsx(
