							initial={{
								opacity: 0,
								y: 8,
							}}
							animate={{
								opacity: 1,
								y: 0,
							}}
							transition={{
								delay: 0.4,
								duration: 0.35,
							}}
							className="mt-4 border rounded-xl p-4 flex gap-4 items-start relative overflow-hidden"
