/* --- Custom UI Icons --- */
const SpeedTacho = ({
	percentage,
	color,
}: {
	percentage: number;
	color: string;
}) => {
	const angle = (percentage / 100) * 180 - 90;
	return (
		<svg
			width="24"
			height="24"
			viewBox="0 0 24 24"
			className="shrink-0 drop-shadow-sm mb-1"
		>
			<path
				d="M 3 17 A 9 9 0 0 1 21 17"
				fill="none"
				stroke={color}
				strokeOpacity="0.25"
				strokeWidth="3.5"
				strokeLinecap="round"
			/>
			<g
				style={{
					transform: `rotate(${angle}deg)`,
					transformOrigin: '12px 17px',
					transition: 'transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
				}}
			>
				<polygon points="12,17 10,17 12,8 14,17" fill={color} />
			</g>
			<circle cx="12" cy="17" r="3" fill={color} />
		</svg>
	);
};

const VolumeBars = ({
	percentage,
	color,
}: {
	percentage: number;
	color: string;
}) => {
	const level =
		percentage <= 25 ? 1 : percentage <= 50 ? 2 : percentage <= 75 ? 3 : 4;
	return (
		<svg
			width="20"
			height="20"
			viewBox="0 0 24 24"
			className="shrink-0 drop-shadow-sm"
		>
			<rect
				x="3"
				y="15"
				width="3.5"
				height="5"
				rx="1.5"
				fill={level >= 1 ? color : `${color}30`}
				style={{
					transition: 'fill 0.4s ease-out',
				}}
			/>
			<rect
				x="8.5"
				y="11"
				width="3.5"
				height="9"
				rx="1.5"
				fill={level >= 2 ? color : `${color}30`}
				style={{
					transition: 'fill 0.4s ease-out 0.1s',
				}}
			/>
			<rect
				x="14"
				y="7"
				width="3.5"
				height="13"
				rx="1.5"
				fill={level >= 3 ? color : `${color}30`}
				style={{
					transition: 'fill 0.4s ease-out 0.2s',
				}}
			/>
			<rect
				x="19.5"
				y="3"
				width="3.5"
				height="17"
				rx="1.5"
				fill={level >= 4 ? color : `${color}30`}
				style={{
					transition: 'fill 0.4s ease-out 0.3s',
				}}
			/>
		</svg>
	);
};

