'use client';

import Link from 'next/link';
import Image from 'next/image';
import {
	Smartphone, Wifi, Zap, Tv, Router, Star,
} from 'lucide-react';
import {
	motion,
} from 'framer-motion';
import {
	SearchBar,
} from '@/components/features/search/search-bar';
import {
	HeroHeader,
} from '@/components/features/products/hero-header';
import {
	NewsCarousel,
} from '@/components/features/news/news-carousel';
import {
	trpc,
} from '@/lib/trpc';
import clsx from 'clsx';
import {
	Skeleton,
} from '@/components/shared/skeleton';
import {
	useEffect, useState,
} from 'react';
import {
	useAnalytics,
} from '@/hooks/use-analytics';
import {
	useSettingsStore,
} from '@/hooks/use-settings-store';

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
   Constants
   ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */

const EASE_OUT_EXPO: [number, number, number, number] = [
	0.16,
	1,
	0.3,
	1,
];
const LS_KEY_FIRST_NAME = 'setup-user-firstName';

const CATEGORIES = [
	{
		id: 'MOBILE',
		title: 'Mobilfunk',
		icon: Smartphone,
		href: '/products/MOBILE',
		color: '#e20074',
		stats: 'Lade Anzahl...',
	},
	{
		id: 'FIBER',
		title: 'Glasfaser',
		icon: Zap,
		href: '/products/FIBER',
		color: '#0090d0',
		stats: 'Lade Anzahl...',
	},
	{
		id: 'DSL',
		title: 'Festnetz',
		icon: Wifi,
		href: '/products/DSL',
		color: '#7b61ff',
		stats: 'Lade Anzahl...',
	},
	{
		id: 'MAGENTA_TV_OTT',
		title: 'MagentaTV ÔÇö OTT',
		icon: Tv,
		href: '/products/MAGENTA_TV_OTT',
		color: '#ff6b00',
		stats: 'Lade Anzahl...',
	},
	{
		id: 'DEVICE',
		title: 'Endger├ñte',
		icon: Router,
		href: '/products/DEVICE',
		color: '#00a878',
		stats: 'Anzahl...',
	},
];

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
   Main Component
   ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */

export default function ProductsPage({
	initialSession,
	initialProducts,
	initialSettings,
}: {
	initialSession?: any;
	initialProducts?: any;
	initialSettings?: any;
}) {
	const {
		data: session, isLoading: sessionLoading,
	} =
		trpc.session.getCurrent.useQuery(undefined, {
			initialData: initialSession,
		});
	const {
		data: allProductsData, isLoading: productsLoading,
	} =
		trpc.product.getAllProducts.useQuery(undefined, {
			initialData: initialProducts,
		});
	const allProducts = allProductsData?.items || [
	];
	const {
		data: designSettings,
	} = trpc.settings.getDesignSettings.useQuery(
		undefined,
		{
			staleTime: 10 * 60 * 1000,
			initialData: initialSettings,
		},
	);
	const isLoading = sessionLoading || productsLoading;
	const utils = trpc.useUtils();
	const {
		trackPageView,
	} = useAnalytics();

	const [
		firstName,
		setFirstName,
	] = useState('');
	const [
		isMounted,
		setIsMounted,
	] = useState(false);

	useEffect(() => {
		trackPageView('/products');
	}, [
		trackPageView,
	]);

	useEffect(() => {
		setIsMounted(true);
		const stored = localStorage.getItem(LS_KEY_FIRST_NAME) ?? '';
		setFirstName(stored);
	}, [
	]);

	// Prefetching all category products manually is no longer needed since
	// allProducts is prefetched and cached locally on first load, so filtering is instant.

	const getStats = (categoryId: string, fallback: string) => {
		if (!allProducts) { return fallback; }
		const count = allProducts.filter((p) => p.category === categoryId).length;
		if (categoryId === 'DEVICE') { return `${count} Ger├ñte`; }
		if (categoryId === 'MAGENTA_TV_OTT') { return `${count} Pakete`; }
		return `${count} Tarife`;
	};

	const highlightedCategories =
		session?.team?.highlights
			.filter((h) => h.category)
			.map((h) => h.category) || [
		];

	const categoryStats = CATEGORIES.map((c) => ({
		name: c.title,
		count: allProducts
			? allProducts.filter((p) => p.category === c.id).length
			: parseInt(c.stats) || 0,
		color: c.color,
	}));

	const {
		showHeroImage,
	} = useSettingsStore();

	return (
		<div className="min-h-full">
			{/* ÔöÇÔöÇÔöÇ Hero Header ÔöÇÔöÇÔöÇ */}
			<HeroHeader
				firstName={isMounted ? firstName : ''}
				teamName={session?.team?.name}
				productsCount={allProducts?.length}
				categories={categoryStats}
				showHeroImage={showHeroImage}
			/>

			{/* ÔöÇÔöÇÔöÇ Search Bar ÔöÇÔöÇÔöÇ */}
			<motion.div
				initial={{
					opacity: 0,
					y: 6,
				}}
				animate={{
					opacity: 1,
					y: 0,
				}}
				transition={{
					delay: 0.12,
					duration: 0.35,
					ease: EASE_OUT_EXPO,
				}}
			>
				<SearchBar />
			</motion.div>

			{/* ÔöÇÔöÇÔöÇ Category Cards ÔöÇÔöÇÔöÇ */}
			{isLoading ? (
				<>
					<div className="grid grid-cols-3 gap-4 mb-4">
						{[
							1,
							2,
							3,
						].map((i) => (
							<Skeleton key={i} className="h-[120px] rounded-[20px]" />
						))}
					</div>
					<div className="grid grid-cols-2 gap-4">
						{[
							4,
							5,
						].map((i) => (
							<Skeleton key={i} className="h-[120px] rounded-[20px]" />
						))}
					</div>
				</>
			) : (
				<>
					<div id="tour-categories">
						{/* Row 1 (3 cards) */}
						<div className="grid grid-cols-3 gap-4 mb-4">
							{CATEGORIES.slice(0, 3).map((category, index) => (
								<CategoryCard
									key={category.id}
									category={category}
									index={index}
									isHighlighted={highlightedCategories.includes(category.id)}
									dynamicStats={getStats(category.id, category.stats)}
									backgroundImage={
