				{/* Hover Background Image Overlay */}
				{backgroundImage && (
					<div className="absolute -inset-0.5 z-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none rounded-[20px] overflow-hidden">
