'use client';

import {
	useState, useEffect, useCallback, useMemo, useRef,
} from 'react';
import {
	useRouter,
} from 'next/navigation';
import {
	trpc,
} from '@/lib/trpc';
import {
	useAnalytics,
} from '@/hooks/use-analytics';
import {
	motion, AnimatePresence,
} from 'framer-motion';
import {
	Check,
	ShieldAlert,
	ArrowRight,
	Users,
	User,
	Mail,
	CheckCircle2,
	RotateCcw,
	ChevronRight,
	MapPin,
	ArrowLeft,
	Search,
} from 'lucide-react';
import clsx from 'clsx';
import {
	TelekomLogo,
} from '@/components/shared/telekom-logo';
import {
	Skeleton,
} from '@/components/shared/skeleton';
import Link from 'next/link';
import {
	GlobalFooter,
} from '@/components/shared/global-footer';
import {
	z,
} from 'zod';

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
   Zod schema for form validation
   ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */

const setupFormSchema = z.object({
	firstName: z.string().trim().min(1, 'Vorname ist erforderlich'),
	lastName: z.string().trim().min(1, 'Nachname ist erforderlich'),
	email: z
		.string()
		.email('Ung├╝ltige E-Mail-Adresse')
		.refine((val) => val.endsWith('@telekom.de'), {
			message: 'Es sind nur interne Adressen erlaubt.',
		}),
	locationId: z.string().min(1, 'Bitte w├ñhle einen Standort aus'),
	teamId: z.string().min(1, 'Bitte w├ñhle ein Team aus'),
	acceptedTerms: z.literal(true),
	acceptedPrivacy: z.literal(true),
});

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
   LocalStorage helpers
   ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */

const LS_KEY_FIRST_NAME = 'setup-user-firstName';
const LS_KEY_LAST_NAME = 'setup-user-lastName';
const LS_KEY_EMAIL = 'setup-user-email';
const LS_KEY_SETUP_DONE = 'setup-completed';

function getStoredUser(): {
	firstName: string;
	lastName: string;
	email: string;
	} {
	if (typeof window === 'undefined') {
		return {
			firstName: '',
			lastName: '',
			email: '',
		};
	}
	return {
		firstName: localStorage.getItem(LS_KEY_FIRST_NAME) ?? '',
		lastName: localStorage.getItem(LS_KEY_LAST_NAME) ?? '',
		email: localStorage.getItem(LS_KEY_EMAIL) ?? '',
	};
}

function persistName(firstName: string, lastName: string, email: string) {
	localStorage.setItem(LS_KEY_FIRST_NAME, firstName);
	localStorage.setItem(LS_KEY_LAST_NAME, lastName);
	localStorage.setItem(LS_KEY_EMAIL, email);
}

function markSetupComplete() {
	localStorage.setItem(LS_KEY_SETUP_DONE, new Date().toISOString());
}

function isSetupAlreadyDone(): boolean {
	if (typeof window === 'undefined') { return false; }
	return !!localStorage.getItem(LS_KEY_SETUP_DONE);
}

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
   Component
   ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */

export default function SetupPage({
	initialLocations,
	initialIsEmailRequired,
	initialIpError,
	initialSession,
}: {
	initialLocations?: any;
	initialIsEmailRequired?: boolean;
	initialIpError?: string | null;
	initialSession?: any;
}) {
	const router = useRouter();
	const {
		trackPageView,
	} = useAnalytics();

	// Form state
	const [
		currentStep,
		setCurrentStep,
	] = useState(1);
	const [
		firstName,
		setFirstName,
	] = useState('');
	const [
		lastName,
		setLastName,
	] = useState('');
	const [
		email,
		setEmail,
	] = useState('');

	const [
		locationSearch,
		setLocationSearch,
	] = useState('');
	const [
		debouncedSearch,
		setDebouncedSearch,
	] = useState('');

	useEffect(() => {
		const timer = setTimeout(() => {
			setDebouncedSearch(locationSearch);
		}, 300);
		return () => clearTimeout(timer);
	}, [
		locationSearch,
	]);

	const [
		selectedLocationId,
		setSelectedLocationId,
	] = useState<string | null>(
		null,
	);
	const [
		selectedTeamId,
		setSelectedTeamId,
	] = useState<string | null>(null);
	const [
		acceptedTerms,
		setAcceptedTerms,
	] = useState(false);
	const [
		acceptedPrivacy,
		setAcceptedPrivacy,
	] = useState(false);
	const [
		isSubmitting,
		setIsSubmitting,
	] = useState(false);
	const [
		pendingSessionId,
		setPendingSessionId,
	] = useState<string | null>(null);
	const [
		formErrors,
		setFormErrors,
	] = useState<Record<string, string>>({
	});

	// Dynamic card height to avoid jumping during AnimatePresence mode="wait"
	const cardRef = useRef<HTMLDivElement>(null);
	const [
		cardHeight,
		setCardHeight,
	] = useState<number | 'auto'>('auto');

	useEffect(() => {
		trackPageView('/setup');
	}, [
		trackPageView,
	]);

	useEffect(() => {
		if (!cardRef.current) { return; }
		const observer = new ResizeObserver((entries) => {
			setCardHeight(
				entries[0].borderBoxSize?.[0]?.blockSize ??
					entries[0].target.getBoundingClientRect().height,
			);
		});
		observer.observe(cardRef.current);
		return () => observer.disconnect();
	}, [
	]);

	// Returning-user state
	const [
		hasCompletedBefore,
		setHasCompletedBefore,
	] = useState(false);
	const [
		showReconfigure,
		setShowReconfigure,
	] = useState(false);

	const {
		data: locations, isLoading: isLocationsLoading,
	} =
		trpc.location.list.useQuery(
			{
				search: debouncedSearch || undefined,
				limit: debouncedSearch ? 100 : 6,
			},
			{
				initialData: debouncedSearch ? undefined : initialLocations,
				refetchOnWindowFocus: false,
			},
		);
	const {
		data: teams, isLoading: isTeamsLoading,
	} = trpc.team.list.useQuery(
		selectedLocationId ? {
			locationId: selectedLocationId,
		} : undefined,
		{
			enabled: !!selectedLocationId,
		},
	);

	const isIpLoading = false; // Prefetched on server
	const isIpError = !!initialIpError;
	const ipError = initialIpError ? {
		message: initialIpError,
	} : null;

	const {
		data: existingSession, refetch: refetchCurrentSession,
	} =
		trpc.session.getCurrent.useQuery(undefined, {
			initialData: initialSession,
			refetchOnWindowFocus: false,
		});

	const requestVerification = trpc.session.requestVerification.useMutation({
		onSuccess: (data) => {
			setIsSubmitting(false);
			if (data.bypassed) {
				finalizeLogin.mutate({
					sessionId: data.sessionId,
				});
			}
			else {
				setPendingSessionId(data.sessionId);
			}
		},
		onError: (error) => {
			console.error('Setup failed', error);
			setIsSubmitting(false);
		},
	});

	const {
		data: verificationStatus,
	} = trpc.session.checkVerification.useQuery(
		{
			sessionId: pendingSessionId as string,
		},
		{
			enabled: !!pendingSessionId,
			refetchInterval: 3000, // Poll every 3 seconds
		},
	);

	const finalizeLogin = trpc.session.finalizeLogin.useMutation({
		onSuccess: (data) => {
			persistName(
				data.firstName?.trim() || '',
				data.lastName?.trim() || '',
				data.email?.trim() || '',
			);
			markSetupComplete();
			refetchCurrentSession().then(() => {
				router.push('/products');
				router.refresh();
			});
		},
		onError: console.error,
	});

	const reloginReturningUser = trpc.session.reloginReturningUser.useMutation({
		onSuccess: (data) => {
			persistName(
				data.firstName?.trim() || '',
				data.lastName?.trim() || '',
				data.email?.trim() || '',
			);
			markSetupComplete();
			refetchCurrentSession().then(() => {
				router.push('/products');
				router.refresh();
			});
		},
		onError: (error) => {
			console.error('Relogin failed:', error);
			// Fallback to Reconfigure flow if re-login failed (e.g., cleared from DB)
			setShowReconfigure(true);
		},
	});

	// Hydrate stored user on mount
	useEffect(() => {
		const stored = getStoredUser();
		if (stored.firstName) { setFirstName(stored.firstName); }
		if (stored.lastName) { setLastName(stored.lastName); }
		if (stored.email) { setEmail(stored.email); }
		setHasCompletedBefore(isSetupAlreadyDone());
	}, [
	]);

	// Listen for verification success
	useEffect(() => {
		if (
			verificationStatus?.verified &&
			pendingSessionId &&
			!finalizeLogin.isPending &&
			!finalizeLogin.isSuccess
		) {
			finalizeLogin.mutate({
				sessionId: pendingSessionId,
			});
		}
	}, [
		verificationStatus?.verified,
		pendingSessionId,
		finalizeLogin,
	]);

	// Show welcome-back if user has completed setup before (localStorage persists
	// beyond the 30-day session cookie, so data survives across re-setups)
	const isReturningUser = hasCompletedBefore;

	const {
		data: isEmailRequiredGlobally,
	} =
		trpc.session.getIsEmailRequired.useQuery(undefined, {
			initialData: initialIsEmailRequired,
		});

	// Zod-based validation
	const validationResult = useMemo(
		() =>
			setupFormSchema.safeParse({
				firstName,
				lastName,
				email:
					isEmailRequiredGlobally === false ? 'no-reply@telekom.de' : email,
				teamId: selectedTeamId ?? '',
				acceptedTerms,
				acceptedPrivacy,
			}),
		[
			firstName,
			lastName,
			email,
			selectedTeamId,
			acceptedTerms,
			acceptedPrivacy,
			isEmailRequiredGlobally,
		],
	);

	const anyFieldEmpty =
		!firstName.trim() ||
		!lastName.trim() ||
		(isEmailRequiredGlobally !== false && !email.trim()) ||
		!selectedLocationId ||
		!selectedTeamId ||
		!acceptedTerms ||
		!acceptedPrivacy;

	const canSubmitClick = !anyFieldEmpty && !isSubmitting && !pendingSessionId;

	const handleNextStep = () => {
		if (currentStep === 1 && selectedLocationId) {
			setCurrentStep(2);
		}
		else if (currentStep === 2 && selectedTeamId) {
			setCurrentStep(3);
		}
	};

	const handlePrevStep = () => {
		if (currentStep > 1) { setCurrentStep(currentStep - 1); }
	};

	const handleSubmit = useCallback(async () => {
		setFormErrors({
		});
		const result = setupFormSchema.safeParse({
			firstName,
			lastName,
			email: isEmailRequiredGlobally === false ? 'no-reply@telekom.de' : email,
			locationId: selectedLocationId ?? '',
			teamId: selectedTeamId ?? '',
			acceptedTerms,
			acceptedPrivacy,
		});

		if (!result.success) {
			const errors: Record<string, string> = {
			};
			for (const issue of result.error.issues) {
				const fieldName = String(issue.path[0]);
				errors[fieldName] = issue.message;
			}
			setFormErrors(errors);
			return;
		}

		setIsSubmitting(true);
		requestVerification.mutate({
			firstName: result.data.firstName,
			lastName: result.data.lastName,
			email: result.data.email,
			teamId: result.data.teamId,
			acceptedTerms: true,
		});
	}, [
		selectedLocationId,
		selectedTeamId,
		acceptedTerms,
		acceptedPrivacy,
		firstName,
		lastName,
		email,
		isEmailRequiredGlobally,
		requestVerification,
	]);

	/* ÔöÇÔöÇ Render Helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */

	const renderStep1 = () => (
		<motion.div
			key="step1"
			initial={{
				opacity: 0,
				x: 15,
			}}
			animate={{
				opacity: 1,
				x: 0,
				transition: {
					delay: 0.4,
					duration: 0.3,
					ease: 'easeOut',
				},
			}}
			exit={{
				opacity: 0,
				x: -15,
				transition: {
					duration: 0.2,
					ease: 'easeIn',
				},
			}}
			className="space-y-6 w-full"
		>
			<SectionHeader
				icon={<MapPin className="w-5 h-5 text-[#e20074]" />}
				title="Standort w├ñhlen"
				step={1}
			/>

			{/* Search Bar */}
			<div className="relative mt-5">
				<div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
					<Search className="w-[18px] h-[18px] text-[#ccc]" />
				</div>
				<input
					type="text"
					value={locationSearch}
					onChange={(e) => setLocationSearch(e.target.value)}
					placeholder="Standort suchen (z.B. Berlin, M├╝nchen)..."
					className="w-full h-[52px] pl-11 pr-4 rounded-xl border border-[#eaedf0] bg-[#f7f8fa] text-[0.95rem] text-[#1a1a2e] font-medium placeholder:text-[#ccc] focus:outline-none focus:border-[#e20074] focus:ring-1 focus:ring-[#e20074]/30 focus:bg-white transition-all shadow-sm"
				/>
			</div>

			{isLocationsLoading ? (
				<div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-5">
					{Array.from({
						length: 6,
					}).map((_, i) => (
						<Skeleton key={i} className="h-[52px] w-full rounded-xl" />
					))}
				</div>
			) : locations?.items?.length === 0 ? (
				<div className="text-center p-8 text-[0.85rem] text-[#aaa] bg-[#f7f8fa] border border-dashed border-[#eaedf0] rounded-2xl mt-5">
					Keine Standorte gefunden.
				</div>
			) : (
				<div className="grid grid-cols-2 gap-3 mt-5">
					<AnimatePresence>
						{locations?.items
							?.filter((loc: any) => loc.isActive)
							.map((loc: any, index: number) => {
								let subtitle = loc.address || '';
								if (loc.odRegion?.name) {
									subtitle = subtitle
										? `${subtitle} ÔÇó ${loc.odRegion.name}`
										: loc.odRegion.name;
								}
								return (
									<SelectionTile
										key={loc.id}
										name={loc.name}
										subtitle={subtitle}
										isSelected={selectedLocationId === loc.id}
										onClick={() => {
											setSelectedLocationId(loc.id);
											setSelectedTeamId(null);
										}}
										index={index}
									/>
								);
							})}
					</AnimatePresence>
				</div>
			)}

			<div className="flex justify-end pt-4 border-t border-[#eaedf0] mt-8">
				<button
					onClick={handleNextStep}
					disabled={!selectedLocationId}
					className={clsx(
						'px-6 py-2.5 rounded-xl font-bold transition-all duration-200 flex items-center gap-2',
						selectedLocationId
							? 'bg-[#e20074] text-white hover:bg-[#c70066] cursor-pointer'
							: 'bg-[#eaedf0] text-[#aaa] cursor-not-allowed',
					)}
				>
					Weiter
					<ArrowRight className="w-4 h-4" />
				</button>
			</div>
		</motion.div>
	);

	const renderStep2 = () => (
		<motion.div
			key="step2"
			initial={{
				opacity: 0,
				x: 15,
			}}
			animate={{
				opacity: 1,
				x: 0,
				transition: {
					delay: 0.4,
					duration: 0.3,
					ease: 'easeOut',
				},
			}}
			exit={{
				opacity: 0,
				x: -15,
				transition: {
					duration: 0.2,
					ease: 'easeIn',
				},
			}}
			className="space-y-6 w-full"
		>
			<SectionHeader
				icon={<Users className="w-5 h-5 text-[#e20074]" />}
				title="Vertriebsteam w├ñhlen"
				step={2}
			/>

			{isTeamsLoading ? (
				<div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-5">
					{Array.from({
						length: 4,
					}).map((_, i) => (
						<Skeleton key={i} className="h-[52px] w-full rounded-xl" />
					))}
				</div>
			) : teams?.items?.length === 0 ? (
				<div className="text-center p-8 text-[0.85rem] text-[#aaa] bg-[#f7f8fa] border border-dashed border-[#eaedf0] rounded-2xl mt-5">
					In diesem Standort wurden noch keine Teams angelegt.
				</div>
			) : (
				<div className="grid grid-cols-2 gap-3 mt-5">
					<AnimatePresence>
						{teams?.items?.map((team: any, index: number) => (
							<SelectionTile
								key={team.id}
								name={team.name}
								isSelected={selectedTeamId === team.id}
								onClick={() => setSelectedTeamId(team.id)}
								index={index}
							/>
						))}
					</AnimatePresence>
				</div>
			)}

			<div className="flex justify-between pt-4 border-t border-[#eaedf0] mt-8">
				<button
					onClick={handlePrevStep}
					className="px-5 py-2.5 rounded-xl font-bold transition-all duration-200 flex items-center gap-2 text-[#666] bg-[#f7f8fa] hover:bg-[#eaedf0] cursor-pointer"
				>
					<ArrowLeft className="w-4 h-4" />
					Zur├╝ck
				</button>
				<button
					onClick={handleNextStep}
					disabled={!selectedTeamId}
					className={clsx(
						'px-6 py-2.5 rounded-xl font-bold transition-all duration-200 flex items-center gap-2',
						selectedTeamId
							? 'bg-[#e20074] text-white hover:bg-[#c70066] cursor-pointer'
							: 'bg-[#eaedf0] text-[#aaa] cursor-not-allowed',
					)}
				>
					Weiter
					<ArrowRight className="w-4 h-4" />
				</button>
			</div>
		</motion.div>
	);

	const renderStep3 = () => (
		<motion.div
			key="step3"
			initial={{
				opacity: 0,
				x: 15,
			}}
			animate={{
				opacity: 1,
				x: 0,
				transition: {
					delay: 0.4,
					duration: 0.3,
					ease: 'easeOut',
				},
			}}
			exit={{
				opacity: 0,
				x: -15,
				transition: {
					duration: 0.2,
					ease: 'easeIn',
				},
			}}
			className="space-y-8 w-full"
		>
			<section>
				<SectionHeader
					icon={<User className="w-5 h-5 text-[#e20074]" />}
					title="Pers├Ânliche Daten"
					step={3}
				/>
				<div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-5">
					<InputField
						id="setup-first-name"
						label="Vorname"
						placeholder="Max"
						value={firstName}
						onChange={setFirstName}
					/>
					<InputField
						id="setup-last-name"
						label="Nachname"
						placeholder="Mustermann"
						value={lastName}
						onChange={setLastName}
					/>
				</div>
				{isEmailRequiredGlobally !== false && (
					<div className="mt-4">
						<InputField
							id="setup-email"
							label="E-Mail-Adresse"
							placeholder="max.mustermann@telekom.de"
							value={email}
							onChange={setEmail}
						/>
