'use client';

import {
	useState, useEffect,
} from 'react';
import {
	motion, AnimatePresence,
} from 'framer-motion';
import {
	TelekomLogo,
} from '@/components/shared/telekom-logo';

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
   Constants & helpers
   ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */

const SPLASH_COOLDOWN_HOURS = 10;
const LS_KEY_SPLASH = 'splash-timestamp';
const LS_KEY_FIRST_NAME = 'setup-user-firstName';

/** Premium easing curve ÔÇô identical to the one used on the setup screen */
const EASE_OUT_EXPO: [number, number, number, number] = [
	0.16,
	1,
	0.3,
	1,
];

function formatDate(): string {
	return new Date().toLocaleDateString('de-DE', {
		day: 'numeric',
		month: 'long',
		year: 'numeric',
	});
}

function getTimeContext(): string {
	const h = new Date().getHours();
	if (h < 12) { return 'Guten Morgen'; }
	if (h < 18) { return 'Guten Tag'; }
	return 'Guten Abend';
}

