													</p>
												</div>
											</div>
										) : (
											<div className="bg-amber-50/80 rounded-2xl p-5 border border-amber-200 flex items-start gap-4">
												<Wifi className="w-8 h-8 text-amber-500 shrink-0 mt-0.5" />
