									window.location.href = `mailto:${teamEmail}?subject=${subject}&body=${bodyText}`;

									setIsGenerating('success');
									if (clearAfterExport) {
										setTimeout(() => clearBasket(), 500);
									}
									setTimeout(() => setIsGenerating('idle'), 10000);
								}}
