'use client';

import {
	useState, useEffect, useRef,
} from 'react';
import {
	trpc,
} from '@/lib/trpc';
import {
	motion, AnimatePresence,
} from 'framer-motion';
import {
	Info,
	AlertCircle,
	AlertTriangle,
	ChevronRight,
	ChevronLeft,
} from 'lucide-react';
import clsx from 'clsx';
import {
	Skeleton,
} from '@/components/shared/skeleton';

const PRIORITY_CONFIG: Record<
	string,
	{ color: string; icon: React.ElementType }
> = {
	INFO: {
		color: '#00a878',
		icon: Info,
	}, // Green
	UPDATE: {
		color: '#0090d0',
		icon: Info,
	}, // Blue
	IMPORTANT: {
		color: '#ff6b00',
		icon: AlertCircle,
	}, // Orange
	CRITICAL: {
		color: '#dc2626',
		icon: AlertTriangle,
	}, // Red
};

export function NewsCarousel() {
	const {
		data: newsItems, isLoading,
	} = trpc.news.listActive.useQuery();
	const [
		currentIndex,
		setCurrentIndex,
	] = useState(0);
	const [
		isPaused,
		setIsPaused,
	] = useState(false);
	const [
		progress,
		setProgress,
	] = useState(0);
	const accumulatedTimeRef = useRef(0);
	const [
		mounted,
		setMounted,
	] = useState(false);

	useEffect(() => {
		setMounted(true);
	}, [
	]);

	// Custom animation loop to manage both the time skipping and progress percentage smoothly with pause support
	useEffect(() => {
		if (!newsItems || newsItems.length <= 1) {
			setProgress(0);
			return;
		}

		let animationFrame: number;
		let lastTime = performance.now();
		const DURATION = 6000;

		const tick = (currentTime: number) => {
			if (!isPaused) {
				const delta = currentTime - lastTime;
				accumulatedTimeRef.current += delta;
				const p = Math.min((accumulatedTimeRef.current / DURATION) * 100, 100);
				setProgress(p);

				if (accumulatedTimeRef.current >= DURATION) {
					accumulatedTimeRef.current = 0;
					setCurrentIndex((prev) => (prev + 1) % newsItems.length);
				}
			}
			lastTime = currentTime;
			animationFrame = requestAnimationFrame(tick);
		};

		animationFrame = requestAnimationFrame(tick);

		return () => cancelAnimationFrame(animationFrame);
	}, [
		newsItems,
		isPaused,
	]);

	if (!mounted || isLoading) {
		return (
			<div className="mt-8 mb-6">
				<div className="rounded-2xl border border-[#eaedf0] bg-white p-5 flex items-start gap-4 h-[100px]">
					<Skeleton className="w-[42px] h-[42px] rounded-xl shrink-0" />
					<div className="flex-1 w-full">
						<Skeleton className="h-5 w-1/3 mb-3" />
						<Skeleton className="h-4 w-3/4 mb-2" />
						<Skeleton className="h-4 w-2/3" />
					</div>
				</div>
			</div>
		);
	}

	if (!newsItems || newsItems.length === 0) {
		return null;
	}

	const currentItem = newsItems[currentIndex] as any;
	const config = PRIORITY_CONFIG[currentItem.priority] || PRIORITY_CONFIG.INFO;
	const Icon = config.icon;

	const handleNext = () => {
		accumulatedTimeRef.current = 0;
		setProgress(0);
		setCurrentIndex((prev) => (prev + 1) % newsItems.length);
	};

	const handlePrev = () => {
		accumulatedTimeRef.current = 0;
		setProgress(0);
		setCurrentIndex((prev) => (prev - 1 + newsItems.length) % newsItems.length);
	};

	const isCritical = currentItem.priority === 'CRITICAL';
	const isImportant = currentItem.priority === 'IMPORTANT';
	const circumference = 2 * Math.PI * 10; // r=10

	let targetLabel = 'Global';
	if (currentItem.team) {
		targetLabel = `F├╝r Dein Team (${currentItem.team.name})`;
	}
	else if (currentItem.location) {
		targetLabel = `F├╝r Deinen Standort (${currentItem.location.name})`;
	}
	else if (currentItem.odRegion) {
		targetLabel = `F├╝r Deinen OD-Bereich (${currentItem.odRegion.name})`;
	}

	return (
		<div
			className="mt-8 mb-6 relative group"
			onMouseEnter={() => setIsPaused(true)}
			onMouseLeave={() => setIsPaused(false)}
		>
			{/* Controls overlaid globally for the carousel */}
			{newsItems.length > 1 && (
				<div className="absolute right-4 top-4 z-30 flex items-center gap-3">
					{/* Navigation Arrows */}
					<div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
						<button
							onClick={handlePrev}
							className="p-1.5 rounded-full bg-black/5 hover:bg-black/10 transition-colors text-[#1a1a2e]/60 hover:text-[#1a1a2e] cursor-pointer"
						>
							<ChevronLeft className="w-4 h-4" />
						</button>
						<button
							onClick={handleNext}
							className="p-1.5 rounded-full bg-black/5 hover:bg-black/10 transition-colors text-[#1a1a2e]/60 hover:text-[#1a1a2e] cursor-pointer"
						>
							<ChevronRight className="w-4 h-4" />
						</button>
					</div>

					{/* Progress Circle Timer */}
					<div
						className="relative w-6 h-6 flex items-center justify-center transition-opacity duration-300"
						title={isPaused ? 'Pausiert' : 'N├ñchste Neuigkeit in...'}
					>
						<svg
							className="w-full h-full -rotate-90"
							style={{
								color: config.color,
							}}
						>
							<circle
								cx="12"
								cy="12"
								r="10"
								stroke="currentColor"
								strokeWidth="2.5"
								fill="none"
								className="opacity-20"
							/>
							<circle
								cx="12"
								cy="12"
								r="10"
								stroke="currentColor"
								strokeWidth="2.5"
								fill="none"
								strokeDasharray={circumference}
								strokeDashoffset={
									circumference - (circumference * progress) / 100
								}
								className="transition-none"
							/>
						</svg>
					</div>
				</div>
			)}

			<div
				className={clsx(
					'relative overflow-hidden rounded-2xl transition-all duration-300',
					isCritical
						? 'border-[3px] shadow-[0_6px_25px_rgba(220,38,38,0.15)]'
						: isImportant
							? 'border-2 shadow-[0_4px_15px_rgba(255,107,0,0.1)]'
							: 'border',
				)}
				style={{
					borderColor: isCritical ? config.color : `${config.color}30`,
					backgroundColor: isCritical
						? `${config.color}0c`
						: `${config.color}06`,
				}}
			>
				{/* Background Glow for Critical */}
				{isCritical && (
					<div className="absolute top-0 right-0 w-64 h-64 bg-linear-to-br from-red-500/10 to-transparent blur-3xl pointer-events-none rounded-full" />
				)}
				{isImportant && (
					<div className="absolute top-0 right-0 w-64 h-64 bg-linear-to-br from-orange-500/10 to-transparent blur-2xl pointer-events-none rounded-full" />
				)}

				<AnimatePresence mode="wait">
					<motion.div
						key={currentItem.id}
						initial={{
							opacity: 0,
							scale: 0.98,
						}}
						animate={{
							opacity: 1,
							scale: 1,
						}}
						exit={{
							opacity: 0,
							scale: 0.98,
						}}
						transition={{
							duration: 0.3,
						}}
						className={clsx(
							'flex items-start gap-4 p-5 z-10 relative',
							isCritical ? 'py-6 px-6' : '',
						)}
					>
						<div
							className={clsx(
								'shrink-0 flex items-center justify-center text-white',
								isCritical
									? 'p-3 rounded-[14px] mt-0.5'
									: 'p-2.5 rounded-xl mt-1',
							)}
							style={{
								backgroundColor: config.color,
							}}
						>
							<Icon className={isCritical ? 'w-6 h-6' : 'w-5 h-5'} />
						</div>

						<div className="flex-1 min-w-0 pr-16 md:pr-32">
							<div className="flex items-center gap-2 mb-1.5">
								<h3
									className={clsx(
										'font-extrabold m-0 tracking-tight',
										isCritical ? 'text-[1.1rem]' : 'text-[0.95rem]',
									)}
									style={{
										color: isCritical ? '#1a1a2e' : config.color,
									}}
								>
									{currentItem.title}
								</h3>
								{isCritical && (
									<span className="px-2.5 py-0.5 rounded-lg text-[0.65rem] font-bold uppercase tracking-wider bg-[#dc2626] text-white shadow-sm ring-2 ring-red-500/20">
										Kritisch
									</span>
								)}
								{isImportant && (
									<span className="px-2 py-0.5 rounded-lg text-[0.65rem] font-bold uppercase tracking-wider bg-[#ff6b00]/10 text-[#ff6b00]">
										Wichtig
									</span>
								)}
								<span className="px-2 py-0.5 rounded-lg text-[0.65rem] font-bold uppercase tracking-wider bg-black/5 text-[#1a1a2e]/60">
									{targetLabel}
								</span>
							</div>
							<p
								className={clsx(
									'm-0 leading-relaxed',
									isCritical
										? 'text-[0.9rem] text-[#1a1a2e] font-semibold'
										: 'text-[0.85rem] text-[#1a1a2e]/80 font-medium',
								)}
							>
								{currentItem.content}
							</p>
						</div>
					</motion.div>
				</AnimatePresence>

				{/* Progress dots - Clickable! */}
				{newsItems.length > 1 && (
					<div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex items-center gap-1.5 z-20">
						{newsItems.map((_: any, i: number) => (
							<button
								key={i}
								onClick={() => {
									accumulatedTimeRef.current = 0;
									setProgress(0);
									setCurrentIndex(i);
								}}
								className={clsx(
									'h-1.5 rounded-full transition-all duration-300 cursor-pointer border-none outline-none',
									i === currentIndex
										? 'w-5 opacity-100 hover:opacity-80'
										: 'w-1.5 opacity-30 hover:opacity-100 hover:w-3',
								)}
								style={{
									backgroundColor: config.color,
								}}
								title={`Zu Meldung ${i + 1} springen`}
							/>
						))}
					</div>
				)}
			</div>
		</div>
	);
}

import {
	useEffect, useRef,
} from 'react';
import {
	useBasketStore, BasketItem,
} from '@/hooks/use-basket-store';
import {
	useNewsNotificationStore,
} from '@/lib/store/news-notification-store';
import {
	calculateProductCosts, DEFAULT_PRICING,
} from '@/hooks/use-cost-calculator';
import {
	trpc,
} from '@/lib/trpc';
import {
	PricingSettings,
} from '@/types/product';

export function useBasketLogic() {
	const {
		items, basketCredits,
	} = useBasketStore();
	const addNotification = useNewsNotificationStore((state) => state.addNotification);
	const lastNudgeRef = useRef<string | null>(null);

	const {
		data: pricingSettings,
	} = trpc.settings.getPricingSettings.useQuery(undefined, {
		staleTime: 10 * 60 * 1000,
	});
	const settings = pricingSettings || DEFAULT_PRICING;

	// Cross-Sell Detector (Fixed + Mobile Advantage)
	useEffect(() => {
		if (items.length === 0) {
			lastNudgeRef.current = null;
			return;
		}

		const hasMobile = items.some((i) => i.product.category === 'MOBILE');
		const hasFixed = items.some(
			(i) => i.product.category === 'FIBER' || i.product.category === 'DSL',
		);

		let nudgeId = null;
		let title = '';
		let content = '';

		if (hasMobile && !hasFixed) {
			nudgeId = 'nudge-fixed-missing';
			title = 'Preisvorteil durch Festnetz';
			content = 'Dein Kunde nutzt Mobilfunk. Biete ihm zus├ñtzlich Festnetz an.';
		}
		else if (hasFixed && !hasMobile) {
			nudgeId = 'nudge-mobile-missing';
			title = 'Preisvorteil durch Mobilfunk';
			content = 'Dein Kunde nutzt Festnetz. Biete ihm zus├ñtzlich Mobilfunk an.';
		}

		if (nudgeId && lastNudgeRef.current !== nudgeId) {
			addNotification({
				id: nudgeId,
				title,
				content,
				priority: 'SALES',
			});
			lastNudgeRef.current = nudgeId;
		}
		else if (!nudgeId) {
			lastNudgeRef.current = null;
		}
	}, [
		items,
		addNotification,
	]);

	// Cache calculations for each item to avoid redundant expensive calls
	const itemsWithCosts = items.map(item => ({
		item,
		costs: calculateProductCosts({
			product: item.product,
			businessCase: item.config.businessCase,
			magentaTVPackage: item.config.magentaTVPackage,
			selectedSpecialPriceIds: item.config.selectedSpecialPriceIds,
			selectedAddonIds: item.config.selectedAddonIds,
			vouchers: item.config.vouchers,
			hardwarePurchaseType: item.config.hardwarePurchaseType,
			plusKartenCount: item.config.plusKartenCount,
			settings,
			customBasePrice: item.config.customBasePrice,
		}),
	}));

	// Aggregated Totals
	const totals = itemsWithCosts.reduce((acc, entry) => {
		return {
			monthly: acc.monthly + entry.costs.averageMonthlyCost,
			daily: acc.daily + entry.costs.averageMonthlyCost / 30,
		};
	}, {
		monthly: 0,
		daily: 0,
	});

	// Monthly steps calculation (24 months)
	const combinedSteps = itemsWithCosts.length > 0 ? (() => {
		const monthlyTotals = Array(24).fill(0);
		itemsWithCosts.forEach((entry) => {
			entry.costs.monthlyCosts.forEach((mc, index) => {
				if (index < 24) { monthlyTotals[index] += mc.total; }
			});
		});

		const steps: { start: number; end: number; total: number }[] = [
		];
		let currentStep = {
			start: 1,
			end: 1,
			total: monthlyTotals[0],
		};

		for (let i = 1; i < 24; i++) {
			if (Math.abs(monthlyTotals[i] - currentStep.total) < 0.01) {
				currentStep.end = i + 1;
			}
			else {
				steps.push({
					...currentStep,
				});
				currentStep = {
					start: i + 1,
					end: i + 1,
					total: monthlyTotals[i],
				};
			}
		}
		steps.push(currentStep);
		return steps;
	})() : [
	];

	// One-time costs breakdown
	const oneTimeBreakdowns = itemsWithCosts.flatMap((entry) => entry.costs.oneTimeCosts.breakdown);

	const oneTimeBreakdownNoShipping = oneTimeBreakdowns.filter(c => c.name !== 'Versand Hardware');
	const totalOneTimeItems = oneTimeBreakdownNoShipping.reduce((acc, curr) => acc + curr.cost, 0);
	const hasDevice = items.some((i) => i.product.category === 'DEVICE');
	const globalShippingFee = hasDevice ? settings.shipping_hardware_fee : 0;

	const groupedOneTimeCosts = oneTimeBreakdownNoShipping.reduce((acc, curr) => {
		acc[curr.name] = (acc[curr.name] || 0) + curr.cost;
		return acc;
	}, {
	} as Record<string, number>);

	if (globalShippingFee > 0) {
		groupedOneTimeCosts['Versand Hardware'] = globalShippingFee;
	}

	const totalCredits = basketCredits.reduce((acc, credit) => acc + credit.value, 0);
	const totalOneTime = (totalOneTimeItems + globalShippingFee) - totalCredits;

	return {
		totals,
		combinedSteps,
		groupedOneTimeCosts,
		totalOneTime,
		totalCredits,
		hasDevice,
		deviceShippingCost: globalShippingFee,
		settings,
	};
}

import {
	useEffect, useMemo, useState,
} from 'react';
import type {
	MagentaTVPackageKey,
} from '@/lib/constants/pricing';
import {
	MAGENTA_TV_PACKAGES,
} from '@/lib/constants/pricing';
import {
	trpc,
} from '@/lib/trpc';
import type {
	Product,
	BusinessCase,
	SpecialPrice,
	CalculationResult,
	Credit,
	PricingSettings,
} from '@/types/product';

export const DEFAULT_PRICING: PricingSettings = {
	magentatv_smart_price: 10,
	magentatv_smartstream_price: 17,
	magentatv_megastream_price: 30,
	shipping_hardware_fee: 6.95,
	plus_karte_first_price: 19.95,
	plus_karte_following_price: 9.95,
};

export type {
	BusinessCase,
};
export type {
	MagentaTVPackageKey,
};

export interface CalculationInput {
    product: Product;
    businessCase: BusinessCase;
    magentaTVPackage: MagentaTVPackageKey | null;
    selectedSpecialPriceIds: string[];
    selectedAddonIds: string[];
    vouchers: number[];
    credits?: Credit[];
    hardwarePurchaseType?: 'RENT' | 'BUY';
    plusKartenCount?: number;
    settings?: PricingSettings;
    customBasePrice?: number;
}

export function calculateProductCosts({
	product,
	businessCase,
	magentaTVPackage,
	selectedSpecialPriceIds,
	selectedAddonIds,
	vouchers,
	credits = [
	],
	hardwarePurchaseType,
	plusKartenCount,
	settings = DEFAULT_PRICING,
	customBasePrice,
}: CalculationInput): CalculationResult {
	if (!product) {
		return {
			monthlyCosts: [
			],
			averageMonthlyCost: 0,
			totalCost24Months: 0,
			oneTimeCosts: {
				total: 0,
				breakdown: [
				],
			},
			basePrice: 0,
			effectiveBasePrice: 0,
			plusKartenCost: 0,
			hasUnlimitedAdvantage: false,
		};
	}

	const isMagentaTVSelected = magentaTVPackage !== null;
	let tvPackagePrice = 0;
	if (magentaTVPackage === 'smart') { tvPackagePrice = settings.magentatv_smart_price; }
	else if (magentaTVPackage === 'smartstream') { tvPackagePrice = settings.magentatv_smartstream_price; }
	else if (magentaTVPackage === 'megastream') { tvPackagePrice = settings.magentatv_megastream_price; }

	const duration = product.contractDuration || 24;

	// 1. Determine Base Price (Standard or Bundle or Hardware)
	let effectiveBasePrice = product.basePrice;

	if (product.category === 'DEVICE') {
		if (hardwarePurchaseType === 'BUY') {
			effectiveBasePrice = 0; // The monthly cost for hardware is 0 if bought
		}
		else if (hardwarePurchaseType === 'RENT') {
			effectiveBasePrice = product.rentalPrice ?? product.basePrice;
		}
		else {
			// Default to rental price or base if none selected
			effectiveBasePrice = product.rentalPrice ?? product.basePrice;
		}
	}
	else {
		// If MagentaTV is selected, we might have a different base price for the bundle
		if (isMagentaTVSelected && product.magentaTVBundlePrice) {
			effectiveBasePrice = product.magentaTVBundlePrice;
		}
	}

	if (customBasePrice !== undefined) {
		effectiveBasePrice = customBasePrice;
	}

	// 2. Determine One-Time Costs (Activation Fee)
	let oneTimeTotal = 0;
	const oneTimeBreakdown: { name: string; cost: number }[] = [
	];

	// Hardware Purchases
	if (product.category === 'DEVICE' && hardwarePurchaseType === 'BUY' && product.purchasePrice) {
		oneTimeTotal += product.purchasePrice;
		oneTimeBreakdown.push({
			name: 'Kaufpreis Endger├ñt',
			cost: product.purchasePrice,
		});
	}

	let activationFee = 0;
	switch (businessCase) {
	case 'NEW_ACTIVATION':
		activationFee = product.activationFeeNew ?? 0;
		break;
	case 'MOVE':
		activationFee = product.activationFeeMove ?? 0;
		break;
	case 'PLAN_CHANGE':
		activationFee = product.activationFeePlanChange ?? 0;
		break;
	case 'SPEED_UP':
		activationFee = product.activationFeeSpeedUp ?? 0;
		break;
	}

	if (activationFee > 0) {
		oneTimeTotal += activationFee;
		oneTimeBreakdown.push({
			name: 'Bereitstellungspauschale Tarif',
			cost: activationFee,
		});
	}

	if (product.category === 'DEVICE') {
		oneTimeTotal += settings.shipping_hardware_fee;
		oneTimeBreakdown.push({
			name: 'Versand Hardware',
			cost: settings.shipping_hardware_fee,
		});
	}

	// Credits
	credits.forEach(credit => {
		oneTimeTotal -= credit.value;
		oneTimeBreakdown.push({
			name: credit.name || 'Gutschrift',
			cost: -credit.value,
		});
	});

	// Subtract one-time vouchers
	const totalVouchers = vouchers.reduce((a, b) => a + b, 0);
	if (totalVouchers > 0) {
		oneTimeTotal -= totalVouchers;
		oneTimeBreakdown.push({
			name: 'Guthaben / Voucher',
			cost: -totalVouchers,
		});
	}

	// 3. Calculate Monthly Costs
	const monthlyCosts = [
	];
	let sumMonthlyCosts = 0;

	// Find selected special price objects
	const activeSpecialPrices = product.specialPrices.filter(sp =>
		selectedSpecialPriceIds.includes(sp.id),
	);

	// Calculate Addon Costs (constant per month for now)
	const activeTiers = (product.compatibleAddons || [
	]).flatMap(a => a.tiers || [
	]).filter(t =>
		selectedAddonIds.includes(t.id),
	);
	const monthlyAddonCost = activeTiers.reduce((sum, tier) => sum + tier.price, 0);

	const pkCount = plusKartenCount || 0;
	const plusKartenCostPerMonth = pkCount >= 1
		? (settings.plus_karte_first_price + Math.max(0, pkCount - 1) * settings.plus_karte_following_price)
		: 0;

	const productNameLower = product.name.toLowerCase();
	const isAtLeastM = productNameLower.includes('magentamobil m') ||
        productNameLower.includes('magentamobil l') ||
        productNameLower.includes('magentamobil xl');
	const hasUnlimitedAdvantage = isAtLeastM && pkCount > 0;

	for (let month = 1; month <= 24; month++) {
		let bestBasePrice = effectiveBasePrice;
		let bestTVCost = tvPackagePrice;

		let appliedBasePriceSpecial: SpecialPrice | undefined;
		let appliedTVSpecial: SpecialPrice | undefined;

		for (const sp of activeSpecialPrices) {
			const matchingTier = sp.tiers.find(t => month >= t.fromMonth && month <= t.toMonth);
			if (matchingTier) {
				const target = matchingTier.discountTarget || sp.discountTarget;
				const type = matchingTier.discountType || sp.discountType;

				if (target === 'MAGENTA_TV') {
					let simulatedCost = type === 'RELATIVE'
						? tvPackagePrice - matchingTier.price
						: matchingTier.price;

					if (simulatedCost < 0) { simulatedCost = 0; }

					if (simulatedCost < bestTVCost) {
						bestTVCost = simulatedCost;
						appliedTVSpecial = sp;
					}
				}
				else {
					let simulatedCost = type === 'RELATIVE'
						? effectiveBasePrice - matchingTier.price
						: matchingTier.price;

					if (simulatedCost < 0) { simulatedCost = 0; }

					if (simulatedCost < bestBasePrice) {
						bestBasePrice = simulatedCost;
						appliedBasePriceSpecial = sp;
					}
				}
			}
		}

		const totalMonthCost = bestBasePrice + monthlyAddonCost + bestTVCost + plusKartenCostPerMonth;
		sumMonthlyCosts += totalMonthCost;

		monthlyCosts.push({
			month,
			basePrice: effectiveBasePrice,
			effectivePrice: bestBasePrice,
			specialPriceApplied: appliedBasePriceSpecial || appliedTVSpecial,
			addonCosts: monthlyAddonCost,
			magentaTVCost: bestTVCost,
			total: totalMonthCost,
		});
	}

	const totalCost24Months = sumMonthlyCosts + oneTimeTotal;
	const averageMonthlyCost = totalCost24Months / 24;

	// Daily price trivialization (using exact monthly average)
	const dailyPrice = averageMonthlyCost / 30;
	const dailyPriceFormatted = dailyPrice < 1
		? `${(dailyPrice * 100).toFixed(0)} Cent`
		: `${dailyPrice.toFixed(2)} Ôé¼`;

	return {
		monthlyCosts,
		averageMonthlyCost,
		totalCost24Months,
		oneTimeCosts: {
			total: oneTimeTotal,
			breakdown: oneTimeBreakdown,
		},
		basePrice: product.basePrice,
		effectiveBasePrice,
		dailyPriceTrivialization: dailyPriceFormatted,
		plusKartenCost: plusKartenCostPerMonth,
		hasUnlimitedAdvantage,
	};
}

export function useCostCalculator(
	product: Product | undefined | null,
	initialBusinessCase: BusinessCase = 'NEW_ACTIVATION',
) {
	const [
		businessCase,
		setBusinessCase,
	] = useState<BusinessCase>(initialBusinessCase);
	const [
		selectedSpecialPriceIds,
		setSelectedSpecialPriceIds,
	] = useState<string[]>([
	]);
	const [
		magentaTVPackage,
		setMagentaTVPackage,
	] = useState<MagentaTVPackageKey | null>(null);
	const [
		selectedAddonIds,
		setSelectedAddonIds,
	] = useState<string[]>([
	]);
	// Vouchers in state
	const [
		vouchers,
		setVouchers,
	] = useState<number[]>([
	]);

	const [
		availableCredits,
		setAvailableCredits,
	] = useState<Credit[]>([
	]);
	const [
		selectedCreditIds,
		setSelectedCreditIds,
	] = useState<string[]>([
	]);

	const [
		hardwarePurchaseType,
		setHardwarePurchaseType,
	] = useState<'RENT' | 'BUY'>('RENT');
	const [
		plusKartenCount,
		setPlusKartenCount,
	] = useState<number>(0);
	const [
		customBasePrice,
		setCustomBasePrice,
	] = useState<number | undefined>(undefined);

	// Derived boolean for backward compat
	const isMagentaTVSelected = magentaTVPackage !== null;

	// Auto-deselect special prices whose conditions are no longer met
	useEffect(() => {
		if (!product || selectedSpecialPriceIds.length === 0) { return; }

		const stillValid = selectedSpecialPriceIds.filter(spId => {
			const sp = product.specialPrices.find(s => s.id === spId);
			if (!sp) { return false; }
			if (sp.requiresMagentaTV && !isMagentaTVSelected) { return false; }
			if (sp.requiresMove && businessCase !== 'MOVE') { return false; }
			if (sp.requiresNewActivation && businessCase !== 'NEW_ACTIVATION') { return false; }
			if (sp.requiresSpeedUp && businessCase !== 'SPEED_UP') { return false; }
			return true;
		});

		if (stillValid.length !== selectedSpecialPriceIds.length) {
			setSelectedSpecialPriceIds(stillValid);
		}
	}, [
		isMagentaTVSelected,
		businessCase,
		product,
		selectedSpecialPriceIds,
	]);

	// Auto-deselect addons whose conditions are no longer met
	useEffect(() => {
		if (!product || !product.compatibleAddons || selectedAddonIds.length === 0) { return; }

		const stillValid = selectedAddonIds.filter(tierId => {
			const addon = product.compatibleAddons!.find(a => (a.tiers || [
			]).some(t => t.id === tierId));
			if (!addon) { return false; }
			if (addon.requiresNoMagentaTV && isMagentaTVSelected) { return false; }
			return true;
		});

		if (stillValid.length !== selectedAddonIds.length) {
			setSelectedAddonIds(stillValid);
		}
	}, [
		isMagentaTVSelected,
		product,
		selectedAddonIds,
	]);

	const {
		data: pricingSettings,
	} = trpc.settings.getPricingSettings.useQuery(undefined, {
		staleTime: 10 * 60 * 1000,
	});
	const settings = pricingSettings || DEFAULT_PRICING;

	const businessCaseOptions = [
		{
			id: 'NEW_ACTIVATION',
			label: 'Neuvertrag',
		},
		{
			id: 'MOVE',
			label: 'Umzug',
		},
		{
			id: 'PLAN_CHANGE',
			label: 'Tarifwechsel',
		},
		{
			id: 'SPEED_UP',
			label: 'Upgrade',
		},
	];

	const calculation = useMemo((): CalculationResult => {
		if (!product) {
			return {
				monthlyCosts: [
				],
				averageMonthlyCost: 0,
				totalCost24Months: 0,
				oneTimeCosts: {
					total: 0,
					breakdown: [
					],
				},
				basePrice: 0,
				effectiveBasePrice: 0,
				plusKartenCost: 0,
				hasUnlimitedAdvantage: false,
			};
		}

		const activeCredits = availableCredits.filter(c => selectedCreditIds.includes(c.id));

		return calculateProductCosts({
			product,
			businessCase,
			magentaTVPackage,
			selectedSpecialPriceIds,
			selectedAddonIds,
			vouchers,
			credits: activeCredits,
			hardwarePurchaseType,
			plusKartenCount,
			settings,
			customBasePrice,
		});
	}, [
		product,
		businessCase,
		magentaTVPackage,
		selectedSpecialPriceIds,
		selectedAddonIds,
		vouchers,
		availableCredits,
		selectedCreditIds,
		hardwarePurchaseType,
		plusKartenCount,
		settings,
		customBasePrice,
	]);

	return {
		businessCase,
		setBusinessCase,
		selectedSpecialPriceIds,
		setSelectedSpecialPriceIds,
		businessCaseOptions,
		isMagentaTVSelected,
		magentaTVPackage,
		setMagentaTVPackage,
		selectedAddonIds,
		setSelectedAddonIds,
		vouchers,
		setVouchers,
		selectedCreditIds,
		setSelectedCreditIds,
		setAvailableCredits,
		calculation,
		hardwarePurchaseType,
		setHardwarePurchaseType,
		plusKartenCount,
		setPlusKartenCount,
		settings,
		customBasePrice,
		setCustomBasePrice,
	};
}

